PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS zones(zone_id INTEGER PRIMARY KEY,zone_code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,region_code TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS skus(sku_id INTEGER PRIMARY KEY,sku_code TEXT NOT NULL UNIQUE,description TEXT NOT NULL,unit_weight_kg REAL NOT NULL CHECK(unit_weight_kg>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS fulfillment_nodes(node_id INTEGER PRIMARY KEY,node_code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,timezone TEXT NOT NULL,cutoff_local_time TEXT NOT NULL CHECK(length(cutoff_local_time)=5 AND (cutoff_local_time GLOB '[01][0-9]:[0-5][0-9]' OR cutoff_local_time GLOB '2[0-3]:[0-5][0-9]')),holiday_calendar_code TEXT NOT NULL REFERENCES holiday_calendars,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS carriers(carrier_id INTEGER PRIMARY KEY,carrier_code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS service_levels(service_level_id INTEGER PRIMARY KEY,service_code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,transit_business_days INTEGER NOT NULL CHECK(transit_business_days>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS carrier_service_levels(carrier_id INTEGER NOT NULL REFERENCES carriers,service_level_id INTEGER NOT NULL REFERENCES service_levels,PRIMARY KEY(carrier_id,service_level_id));
CREATE TABLE IF NOT EXISTS service_zones(service_level_id INTEGER NOT NULL REFERENCES service_levels,zone_id INTEGER NOT NULL REFERENCES zones,PRIMARY KEY(service_level_id,zone_id));
CREATE TABLE IF NOT EXISTS node_service_zones(node_id INTEGER NOT NULL REFERENCES fulfillment_nodes,zone_id INTEGER NOT NULL REFERENCES zones,PRIMARY KEY(node_id,zone_id));
CREATE TABLE IF NOT EXISTS holiday_calendars(holiday_calendar_code TEXT PRIMARY KEY,calendar_name TEXT NOT NULL,region_code TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS holidays(holiday_calendar_code TEXT NOT NULL REFERENCES holiday_calendars,holiday_date TEXT NOT NULL CHECK(date(holiday_date) IS NOT NULL),holiday_name TEXT NOT NULL,PRIMARY KEY(holiday_calendar_code,holiday_date));
CREATE TABLE IF NOT EXISTS orders(order_id INTEGER PRIMARY KEY,order_number TEXT NOT NULL UNIQUE,ordered_at TEXT NOT NULL CHECK(datetime(ordered_at) IS NOT NULL),destination_zone_id INTEGER NOT NULL REFERENCES zones,status TEXT NOT NULL CHECK(status IN('pending','allocated','partially_fulfilled','fulfilled','delivered','cancelled','exception')),currency TEXT NOT NULL CHECK(length(currency)=3),created_at TEXT NOT NULL CHECK(datetime(created_at) IS NOT NULL));
CREATE TABLE IF NOT EXISTS order_lines(order_line_id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders,line_number INTEGER NOT NULL CHECK(line_number>0),sku_id INTEGER NOT NULL REFERENCES skus,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price REAL NOT NULL CHECK(unit_price>=0),UNIQUE(order_id,line_number),UNIQUE(order_line_id,order_id));
CREATE TABLE IF NOT EXISTS inventory(node_id INTEGER NOT NULL REFERENCES fulfillment_nodes,sku_id INTEGER NOT NULL REFERENCES skus,on_hand_quantity INTEGER NOT NULL CHECK(on_hand_quantity>=0),reserved_quantity INTEGER NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0),PRIMARY KEY(node_id,sku_id),CHECK(reserved_quantity<=on_hand_quantity));
CREATE TABLE IF NOT EXISTS warehouse_capacity(node_id INTEGER NOT NULL REFERENCES fulfillment_nodes,capacity_date TEXT NOT NULL CHECK(date(capacity_date) IS NOT NULL),capacity_units INTEGER NOT NULL CHECK(capacity_units>=0),PRIMARY KEY(node_id,capacity_date));
CREATE TABLE IF NOT EXISTS shipments(shipment_id INTEGER PRIMARY KEY,shipment_number TEXT NOT NULL UNIQUE,order_id INTEGER NOT NULL REFERENCES orders,node_id INTEGER NOT NULL REFERENCES fulfillment_nodes,carrier_id INTEGER NOT NULL REFERENCES carriers,service_level_id INTEGER NOT NULL REFERENCES service_levels,destination_zone_id INTEGER NOT NULL REFERENCES zones,status TEXT NOT NULL CHECK(status IN('planned','allocated','label_created','dispatched','in_transit','delivered','exception','returned','cancelled')),created_at TEXT NOT NULL CHECK(datetime(created_at) IS NOT NULL),UNIQUE(shipment_id,order_id));
CREATE TABLE IF NOT EXISTS shipment_lines(shipment_id INTEGER NOT NULL,order_id INTEGER NOT NULL,order_line_id INTEGER NOT NULL,allocated_quantity INTEGER NOT NULL CHECK(allocated_quantity>0),PRIMARY KEY(shipment_id,order_line_id),FOREIGN KEY(shipment_id,order_id) REFERENCES shipments(shipment_id,order_id),FOREIGN KEY(order_line_id,order_id) REFERENCES order_lines(order_line_id,order_id));
CREATE TABLE IF NOT EXISTS inventory_transactions(inventory_transaction_id INTEGER PRIMARY KEY,transaction_key TEXT NOT NULL UNIQUE,node_id INTEGER NOT NULL,sku_id INTEGER NOT NULL,order_id INTEGER REFERENCES orders,order_line_id INTEGER REFERENCES order_lines,shipment_id INTEGER REFERENCES shipments,transaction_type TEXT NOT NULL CHECK(transaction_type IN('reserve','release','consume','restock','adjustment')),quantity INTEGER NOT NULL CHECK(quantity>0),occurred_at TEXT NOT NULL CHECK(datetime(occurred_at) IS NOT NULL),note TEXT,FOREIGN KEY(node_id,sku_id) REFERENCES inventory(node_id,sku_id));
CREATE TABLE IF NOT EXISTS tracking_events(tracking_event_id INTEGER PRIMARY KEY,shipment_id INTEGER NOT NULL REFERENCES shipments,event_sequence INTEGER NOT NULL CHECK(event_sequence>0),event_type TEXT NOT NULL CHECK(event_type IN('label_created','picked_up','in_transit','out_for_delivery','delivered','exception','exception_cleared','return_initiated','returned','cancelled')),event_status TEXT NOT NULL CHECK(event_status IN('label_created','picked_up','in_transit','out_for_delivery','delivered','exception','return_initiated','returned','cancelled')),event_at TEXT NOT NULL CHECK(datetime(event_at) IS NOT NULL),location TEXT,exception_code TEXT,exception_detail TEXT,source_event_id TEXT,UNIQUE(shipment_id,event_sequence),CHECK((event_status='exception' AND exception_code IS NOT NULL) OR (event_status<>'exception' AND exception_code IS NULL)));
CREATE TABLE IF NOT EXISTS order_delivery_promises(order_promise_id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders,revision INTEGER NOT NULL CHECK(revision>0),promised_at TEXT NOT NULL CHECK(datetime(promised_at) IS NOT NULL),calculated_at TEXT NOT NULL CHECK(datetime(calculated_at) IS NOT NULL),rule_version TEXT NOT NULL,reason TEXT,UNIQUE(order_id,revision));
CREATE TABLE IF NOT EXISTS shipment_delivery_promises(shipment_promise_id INTEGER PRIMARY KEY,shipment_id INTEGER NOT NULL REFERENCES shipments,revision INTEGER NOT NULL CHECK(revision>0),promised_at TEXT NOT NULL CHECK(datetime(promised_at) IS NOT NULL),calculated_at TEXT NOT NULL CHECK(datetime(calculated_at) IS NOT NULL),rule_version TEXT NOT NULL,reason TEXT,UNIQUE(shipment_id,revision));
CREATE INDEX IF NOT EXISTS idx_orders_ordered_at ON orders(ordered_at);
CREATE INDEX IF NOT EXISTS idx_orders_destination_zone ON orders(destination_zone_id);
CREATE INDEX IF NOT EXISTS idx_order_lines_sku ON order_lines(sku_id);
CREATE INDEX IF NOT EXISTS idx_inventory_sku_node ON inventory(sku_id,node_id);
CREATE INDEX IF NOT EXISTS idx_capacity_date_node ON warehouse_capacity(capacity_date,node_id);
CREATE INDEX IF NOT EXISTS idx_shipments_order ON shipments(order_id);
CREATE INDEX IF NOT EXISTS idx_shipments_node_date ON shipments(node_id,created_at);
CREATE INDEX IF NOT EXISTS idx_shipments_carrier_service ON shipments(carrier_id,service_level_id);
CREATE INDEX IF NOT EXISTS idx_shipment_lines_line ON shipment_lines(order_line_id);
CREATE INDEX IF NOT EXISTS idx_inventory_tx_stock_time ON inventory_transactions(node_id,sku_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_inventory_tx_order ON inventory_transactions(order_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_inventory_tx_shipment ON inventory_transactions(shipment_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_tracking_shipment_time ON tracking_events(shipment_id,event_at);
CREATE INDEX IF NOT EXISTS idx_tracking_type_time ON tracking_events(event_type,event_at);
CREATE INDEX IF NOT EXISTS idx_order_promises_order_time ON order_delivery_promises(order_id,calculated_at);
CREATE INDEX IF NOT EXISTS idx_shipment_promises_shipment_time ON shipment_delivery_promises(shipment_id,calculated_at);

CREATE TRIGGER IF NOT EXISTS inventory_transactions_no_update BEFORE UPDATE ON inventory_transactions BEGIN SELECT RAISE(ABORT,'inventory transaction history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS inventory_transactions_no_delete BEFORE DELETE ON inventory_transactions BEGIN SELECT RAISE(ABORT,'inventory transaction history is append-only'); END;
